import { Component, inject, signal, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { TipoDocumentoMaestroService } from '../../../../../shared/services/tipo-documento-maestro.service';
import { TipoDocumentoMaestro, PaginatedTiposDocumentoMaestro } from '../../../../../shared/models/tipo-documento-maestro.model';
import { PaginatorComponent } from '../../../../../shared/components/paginator/paginator.component';
import { extractErrorMessage } from '../../../../../shared/utils/error-utils';
import { ToastService } from '../../../../../shared/services/toast.service';

@Component({
  selector: 'app-tipos-documento-list',
  imports: [PaginatorComponent],
  templateUrl: './tipos-documento-list.component.html',
})
export class TiposDocumentoListComponent implements OnInit {
  private readonly tipoDocumentoService = inject(TipoDocumentoMaestroService);
  private readonly router = inject(Router);
  protected readonly page = signal(1);
  protected readonly perPage = signal(15);
  protected readonly tiposDocumento = signal<TipoDocumentoMaestro[]>([]);
  protected readonly total = signal(0);
  protected readonly lastPage = signal(1);
  protected readonly loading = signal(false);

  ngOnInit(): void {
    this.loadTiposDocumento();
  }

  protected loadTiposDocumento(): void {
    this.loading.set(true);
    this.tipoDocumentoService.getAll(this.page()).subscribe({
      next: (result: PaginatedTiposDocumentoMaestro) => {
        this.tiposDocumento.set(result.data);
        this.total.set(result.total);
        this.lastPage.set(result.last_page);
        this.perPage.set(result.per_page);
        this.loading.set(false);
      },
      error: () => {
        this.loading.set(false);
      },
    });
  }

  protected onPageChange(page: number): void {
    this.page.set(page);
    this.loadTiposDocumento();
  }

  protected onNuevo(): void {
    this.router.navigate(['/ejecutivos/configuracion/tipos-documento/nuevo']);
  }

  protected onEditar(id: number): void {
    this.router.navigate(['/ejecutivos/configuracion/tipos-documento', id, 'editar']);
  }

  private readonly toastService = inject(ToastService);
  protected readonly showDeleteModal = signal(false);
  protected readonly idToDelete = signal<number | null>(null);

  protected onEliminar(id: number): void {
    this.idToDelete.set(id);
    this.showDeleteModal.set(true);
  }

  protected cancelEliminar(): void {
    this.idToDelete.set(null);
    this.showDeleteModal.set(false);
  }

  protected confirmEliminar(): void {
    const id = this.idToDelete();
    if (id === null) return;

    this.tipoDocumentoService.delete(id).subscribe({
      next: () => {
        this.toastService.success('Tipo de documento eliminado exitosamente.');
        this.cancelEliminar();
        this.loadTiposDocumento();
      },
      error: (err) => {
        this.toastService.error(extractErrorMessage(err));
        this.cancelEliminar();
      },
    });
  }
}
